import {TokenType as tt} from "../parser/tokenizer/types";


export default function elideImportEquals(tokens) {

  tokens.removeInitialToken();

  tokens.removeToken();

  tokens.removeToken();

  tokens.removeToken();

  if (tokens.matches1(tt.parenL)) {

    tokens.removeToken();

    tokens.removeToken();

    tokens.removeToken();
  } else {
    while (tokens.matches1(tt.dot)) {

      tokens.removeToken();

      tokens.removeToken();
    }
  }
}
